params.source:
(() => {
    const Native = VideoEncoder;
    window.completeFrameTest = {
      omitted: 0,
      encoders: []
    };
    window.VideoEncoder = class extends Native {
      constructor(init) {
        super({
          ...init,
          output: (chunk, metadata) => {
            if (chunk.timestamp === 33333) {
              window.completeFrameTest.omitted++;
              return;
            }
            init.output(chunk, metadata);
          }
        });
        window.completeFrameTest.encoders.push(this);
      }
    };
  })(undefined)

params.expression:
() => new Promise((resolve, reject) => {
    const request = indexedDB.open('shot-studio-sequence-documents', 1);
    request.onerror = () => reject(request.error);
    request.onupgradeneeded = () => request.transaction.abort();
    request.onsuccess = () => {
      const db = request.result,
        tx = db.transaction('state', 'readonly'),
        store = tx.objectStore('state');
      const key = store.getKey('sequence'),
        value = store.get('sequence');
      tx.onerror = () => {
        db.close();
        reject(tx.error);
      };
      tx.onabort = () => {
        db.close();
        reject(tx.error);
      };
      tx.oncomplete = () => {
        db.close();
        resolve({
          present: key.result !== undefined,
          row: key.result === undefined ? null : {
            schemaVersion: value.result.schemaVersion,
            revision: value.result.revision,
            legacyRaw: value.result.legacyRaw,
            archive: Array.from(new Uint8Array(value.result.archive))
          },
          legacy: localStorage.getItem('shot-studio-sequence-v1')
        });
      };
    };
  })
